class Solution {
        static class SegmentTree {
                int n, k;
                        int[] prod;
                                int[][] count;

                                        public SegmentTree(int[] nums, int k) {
                                                    this.n = nums.length;
                                                                this.k = k;
                                                                            this.prod = new int[4 * n];
                                                                                        this.count = new int[4 * n][k];
                                                                                                    build(nums, 0, 0, n - 1);
                                                                                                            }

                                                                                                                    private void merge(int node, int left, int right) {
                                                                                                                                prod[node] = (prod[left] * prod[right]) % k;
                                                                                                                                            for (int r = 0; r < k; r++) {
                                                                                                                                                            count[node][r] = count[left][r];
                                                                                                                                                                        }
                                                                                                                                                                                    int lProd = prod[left];
                                                                                                                                                                                                for (int r = 0; r < k; r++) {
                                                                                                                                                                                                                int newRem = (lProd * r) % k;
                                                                                                                                                                                                                                count[node][newRem] += count[right][r];
                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                            private void build(int[] nums, int node, int l, int r) {
                                                                                                                                                                                                                                                                        if (l == r) {
                                                                                                                                                                                                                                                                                        int val = nums[l] % k;
                                                                                                                                                                                                                                                                                                        prod[node] = val;
                                                                                                                                                                                                                                                                                                                        count[node][val] = 1;
                                                                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                int mid = l + (r - l) / 2;
                                                                                                                                                                                                                                                                                                                                                                            build(nums, 2 * node + 1, l, mid);
                                                                                                                                                                                                                                                                                                                                                                                        build(nums, 2 * node + 2, mid + 1, r);
                                                                                                                                                                                                                                                                                                                                                                                                    merge(node, 2 * node + 1, 2 * node + 2);
                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                    public void update(int node, int l, int r, int idx, int val) {
                                                                                                                                                                                                                                                                                                                                                                                                                                if (l == r) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                int v = val % k;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                prod[node] = v;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                for (int i = 0; i < k; i++) count[node][i] = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                count[node][v] = 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        int mid = l + (r - l) / 2;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (idx <= mid) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    update(2 * node + 1, l, mid, idx, val);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                update(2 * node + 2, mid + 1, r, idx, val);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        merge(node, 2 * node + 1, 2 * node + 2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Returns {product, count_array} for query range [qL, qR]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                public Result query(int node, int l, int r, int qL, int qR) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (qL <= l && r <= qR) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return new Result(prod[node], count[node]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    int mid = l + (r - l) / 2;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (qR <= mid) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return query(2 * node + 1, l, mid, qL, qR);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (qL > mid) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return query(2 * node + 2, mid + 1, r, qL, qR);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Result leftRes = query(2 * node + 1, l, mid, qL, qR);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Result rightRes = query(2 * node + 2, mid + 1, r, qL, qR);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        int combinedProd = (leftRes.prod * rightRes.prod) % k;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    int[] combinedCount = new int[k];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                for (int rMod = 0; rMod < k; rMod++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                combinedCount[rMod] = leftRes.count[rMod];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        for (int rMod = 0; rMod < k; rMod++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        int newRem = (leftRes.prod * rMod) % k;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        combinedCount[newRem] += rightRes.count[rMod];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return new Result(combinedProd, combinedCount);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                static class Result {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        int prod;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                int[] count;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Result(int prod, int[] count) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    this.prod = prod;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                this.count = count;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                public int[] resultArray(int[] nums, int k, int[][] queries) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        int n = nums.length;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                SegmentTree tree = new SegmentTree(nums, k);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        int[] ans = new int[queries.length];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                for (int i = 0; i < queries.length; i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            int idx = queries[i][0];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        int val = queries[i][1];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    int start = queries[i][2];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                int targetX = queries[i][3];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            tree.update(0, 0, n - 1, idx, val);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Result res = tree.query(0, 0, n - 1, start, n - 1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ans[i] = res.count[targetX];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return ans;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
